import {trailCases,trailPages,trailExample,changedWhole} from './fraction-trail-content.mjs';
import * as core from './fraction-trail-core.mjs';
import {ribbonLine,guidePreview,changedWholeArt} from './fraction-trail-art.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const title=s=>s.charAt(0).toUpperCase()+s.slice(1);
const button=(text,attrs='',primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" ${attrs}>${text}</button>`;
const names={2:'half',3:'third',4:'quarter',6:'sixth'};
export function fractionTrailEntry(){return `<section class="fraction-trail-entry"><h2>Fraction Trail</h2><p>Build the spaces on a ribbon, then choose where the flag belongs.</p><a class="secondary" href="#cafe/fractions">Visit Fraction Trail</a></section>`;}
function feedbackPanel(kind,h){
 if(!h)return '';const o=h.outcomes;let text='';
 if(kind==='spaces')text=`${o.spaceCountMatches?'The number of spaces fits this request.':'The number of spaces does not yet fit this request.'} ${o.equalSpaces?'The spaces within each whole are equal in length.':'The spaces within each whole are unequal. Count the spaces, then compare their lengths.'}`;
 if(kind==='stop')text=!o.flagPresent?'There is no flag yet. Start at zero, then move one space at a time.':`${o.pointMatches?'The flag is at the requested point.':'The flag is not at the requested point yet.'} ${o.partitionMatches?'The spaces also fit the requested partition.':'The partition does not yet fit this request. Check both the number and the equal lengths of its spaces.'}`;
 if(kind==='reading')text=o.readingMatches?'Your reading names the actual flag location. This checks your reading of the flag; the requested stop has its own check.':'Your reading does not name the actual flag location yet. Read from zero to the flag, using one whole as your reference.';
 return `<section class="fraction-feedback" id="trail-feedback-${kind}" tabindex="-1" role="status"><h3>${{spaces:'About the spaces',stop:'About the requested stop',reading:'About your reading of the actual flag'}[kind]}</h3><p>${text}</p>${h.priorExposureUnknown?'<p class="tiny">Earlier encounters are unknown; this is '+(h.checkedPreviously?'another check recorded since recovery.':'the first check recorded since recovery.')+'</p>':''}</section>`;
}
function flagControls(v){const n=v.boundaries.length-1,at=v.case.markerIndex;return `<div class="fraction-actions" id="trail-flag-controls" role="group" aria-label="Move the flag on the ribbon" tabindex="-1">${button('Start the flag at zero','data-trail-start',true)}${button('Back one space',`data-trail-back ${at===null||at===0?'disabled':''}`)}${button('Forward one space',`data-trail-forward ${at===null||at===n?'disabled':''}`)}</div>`;}
function modelCaption(v){const n=v.spaceCount,eq=v.equalSpaces;return `<p class="fraction-line-caption">${n} ${n===1?'space':'spaces'} in each whole; ${2*n+1} boundary marks across the line. ${eq?(names[n]?`Each equal space is one ${names[n]} of a whole ribbon.`:'The spaces are equal.'):'These spaces have different lengths.'} ${v.case.markerIndex===null?'The flag has not been started.':`The flag is ${v.case.markerIndex} ${v.case.markerIndex===1?'space':'spaces'} from zero.`}</p>`;}
function helpPanel(v){const w=v.case,topic=w.helpTopic;let content='';
 if(topic==='units')content='<h3>Keep one whole in view</h3><p>The bracket from 0 to 1 shows one whole ribbon. From 1 to 2 is another whole of exactly the same length. Dividing the ribbon changes its spaces, not the size of its whole.</p><p>For thirds, each whole has three equal spaces. One space is one third of that whole.</p>';
 if(topic==='boundaries')content='<h3>Count spaces between marks</h3><p>Zero is the starting boundary. Three spaces have four boundary marks, including the two ends. Put a finger in each space as you count; the marks are its edges.</p>';
 if(topic==='changed-whole')content=`<h3>When the whole changes</h3>${changedWholeArt()}<p>${esc(changedWhole.caption)}</p><p>${esc(changedWhole.question)}</p>`;
 if(topic==='example'){
 const step=w.exampleStep;content=`<h3>${esc(trailExample.title)}</h3><p>This is a separate ribbon. Your own line stays as you left it.</p>${ribbonLine({cuts:step>=2?trailExample.cuts:[],markerIndex:step>=3?1:null,label:trailExample.title})}${step?`<p>${esc(trailExample.steps[step-1])}</p>`:'<p>Look at one whole, divide it, then take one third-length step.</p>'}${button(step===0?'Begin the example':'Next example step',`data-trail-example ${step>=4?'disabled':''}`)}${step>=4?'<p>The example ends at one third. Try your own request whenever you like.</p>':''}`;
 }
 return `<details class="fraction-help" ${topic?'open':''}><summary>Some help, if you like</summary><div class="fraction-help-options">${[['units','What is one whole?'],['boundaries','Spaces and boundary marks'],['example','See a separate example'],['changed-whole','Compare two whole ribbons']].map(([id,label])=>button(label,`data-trail-help="${id}" aria-pressed="${topic===id}"`)).join('')}</div><fieldset><legend>Prepare equal spaces together</legend><p class="tiny">These buttons supply the partition as help. They remove the flag so you can place it again.</p><div class="fraction-actions">${[2,3,4,6].map(n=>button(`${n} equal spaces`,`data-trail-prepare="${n}"`)).join('')}</div></fieldset><div class="fraction-actions">${button('Prepare this request together','data-trail-together')}<span class="tiny">Supplies a partition and its flag. Checking and keeping are still your choices.</span></div>${topic?`<section class="fraction-help-content" id="trail-help-content" tabindex="-1">${content}${button('Close this help','data-trail-help=""')}</section>`:''}</details>`;
}
function buildPage(v){return `<section class="fraction-work"><h2 id="trail-page-title" tabindex="-1">Build the spaces</h2><p class="fraction-page-intro">Choose guides below to add or remove solid division marks. The second whole repeats the same spaces.</p><fieldset><legend>Places to divide the first whole</legend><p class="tiny">Each little preview shows a guide within one whole, from its left edge to its right edge. Faint guides are possibilities; solid marks divide the ribbon.</p><div class="fraction-guide-grid">${Array.from({length:11},(_,i)=>i+1).map(t=>`<button type="button" class="fraction-guide" data-trail-cut="${t}" aria-label="${v.case.cuts.includes(t)?'Remove':'Add'} division at guide ${t}, counted from the left" aria-pressed="${v.case.cuts.includes(t)}">${guidePreview(t)}<span>${v.case.cuts.includes(t)?'Remove':'Add'} guide ${t}</span></button>`).join('')}</div></fieldset><div class="fraction-actions">${button('Check the spaces','data-trail-check="spaces"',true)}</div>${feedbackPanel('spaces',v.feedback.spaces)}<p id="trail-cut-notice" role="status" tabindex="-1" class="tiny">Changing the spaces removes the flag. Place it again on your new spaces.</p></section>`;}
function placePage(v){return `<section class="fraction-work"><h2 id="trail-page-title" tabindex="-1">Place the stop</h2><p class="fraction-page-intro">Start at zero. Move the flag one current space at a time. You can cross one whole and continue into the next.</p>${flagControls(v)}<div class="fraction-actions">${button('Check the requested stop','data-trail-check="stop"',true)}</div>${feedbackPanel('stop',v.feedback.stop)}</section>`;}
function readPage(v){const w=v.case;return `<section class="fraction-work"><h2 id="trail-page-title" tabindex="-1">Read your flag</h2><p class="fraction-page-intro">What number names the flag’s actual location? It can be different from the requested stop.</p>${flagControls(v)}<div class="fraction-reading"><label for="trail-reading">My reading of the flag</label><input id="trail-reading" type="text" inputmode="text" maxlength="24" value="${esc(w.readingText)}" placeholder="A fraction or whole number" aria-describedby="trail-reading-hint${w.inputError?' trail-input-error':''}" ${w.inputError?'aria-invalid="true"':''} autocomplete="off" spellcheck="false"><p id="trail-reading-hint" class="tiny">You can write a whole number or a fraction such as 1/2. Equivalent fractions are welcome.</p></div>${w.inputError?`<p class="fraction-error" id="trail-input-error" tabindex="-1" role="alert">${esc(w.inputError)}</p>`:''}<div class="fraction-actions">${button('Check my reading','data-trail-check="reading"',true)}</div>${feedbackPanel('reading',v.feedback.reading)}</section>`;}
function keepPage(v){const k=v.kept;return `<section class="fraction-work"><h2 id="trail-page-title" tabindex="-1">Keep a route card</h2><p class="fraction-page-intro">Keep this work just as it is. An unfinished line is welcome too. Your kept card stays frozen while you change the current line.</p><div class="fraction-actions">${button(k?'Keep this version instead':'Keep this route','data-trail-keep',true)}</div>${k?`<div class="fraction-keep-comparison"><section class="fraction-snapshot"><h3 id="trail-kept-title" tabindex="-1">Kept route</h3><p>${esc(k.source.request)}</p>${ribbonLine({...k,label:'Kept route'})}<p>Reading kept: ${k.readingText?`“${esc(k.readingText)}”`:'no reading yet'}. ${k.ready?'The requested partition and flag matched when kept.':'Kept as work to revisit.'}</p></section><section class="fraction-snapshot"><h3>Current route</h3>${ribbonLine({...v.case,label:'Current route'})}<p>Current reading: ${v.case.readingText?`“${esc(v.case.readingText)}”`:'no reading yet'}.</p></section></div><p>Both lines use the same scale. Compare the flags with the same one-whole bracket.</p>`:'<p id="trail-empty-keep">No route kept for this request yet.</p>'}</section>`;}
export function renderFractionTrail(state){const v=core.trailView(state);
 if(v.unsupported)return {html:`<div class="fraction-trail"><a href="#cafe">Back to the café</a><h1>Fraction Trail</h1><p>This saved trail uses a format this version cannot play. Its original work is kept in your notes.</p><a href="#notes">Visit your notes</a><div class="fraction-actions">${button('Keep the original and start a fresh trail','data-trail-recover',true)}</div></div>`,facts:[]};
 const pages={build:buildPage,place:placePage,read:readPage,keep:keepPage};
 return {html:`<div class="fraction-trail"><a class="back" href="#cafe">Back to the café</a><header class="fraction-trail-head"><div><h1>Fraction Trail</h1><p>A ribbon for the gathering. Where shall its flag go?</p></div><label class="fraction-case-picker" for="trail-case">Choose a request<select id="trail-case">${trailCases.map(c=>`<option value="${c.id}" ${c.id===v.source.id?'selected':''}>${esc(c.title)}</option>`).join('')}</select></label></header><nav class="fraction-pages" aria-label="Fraction Trail pages">${trailPages.map(p=>`<button type="button" data-trail-page="${p}" ${p===v.root.page?'aria-current="page"':''}>${title(p)}</button>`).join('')}</nav><section class="fraction-request" aria-label="Current request"><p>${esc(v.source.request)}</p>${hearButton(v.source.request,'Hear this request')}</section><section class="fraction-map" aria-label="Working ribbon">${ribbonLine({...v.case,label:'Working ribbon',guides:v.root.page==='build'})}${modelCaption(v)}</section>${pages[v.root.page](v)}${helpPanel(v)}<footer><p class="fraction-support-note">Look, try, talk it through. Every page and request is open.</p><a href="#cafe/sharing">Visit the Sharing Counter</a> · <a href="#explore">Follow another curiosity</a></footer></div>`,facts:[]};
}
export function fractionTrailNotes(state){
 if(!Object.hasOwn(state,'fractionTrail'))return '';const v=core.trailView(state);
 if(v.unsupported)return `<section class="panel fraction-notes"><h2>Fraction Trail</h2><p>Unsupported saved work retained unchanged. Trail actions are paused until an explicit fresh start.</p><pre>${esc(JSON.stringify(state.fractionTrail,null,2))}</pre></section>`;
 return `<details class="panel fraction-notes"><summary>Fraction Trail: routes and pictured practice</summary><p>These are local choices with a visible model and any amount of help. They do not establish independent recall, reading, fraction mastery or completed travel.</p>${v.priorExposureUnknown?'<p>Earlier encounters are unknown. All later checks and keeps retain that qualification.</p><details><summary>Original recovered work</summary><pre>'+esc(JSON.stringify(v.root.recovered,null,2))+'</pre></details>':''}${Object.values(v.root.cases).map(w=>`<section><h3>${esc(w.source.title)}</h3><p>Current raw reading: “${esc(w.readingText)}”. ${w.familiar?'Request revisited.':'No revisit recorded.'} Support: ${w.support.map(esc).join(', ')}.</p><p>${w.history.length} retained checks. ${w.kept?'A frozen route is kept.':'No route kept.'}</p><details><summary>Exact current model, checks and kept work</summary><pre>${esc(JSON.stringify(w,null,2))}</pre></details></section>`).join('')}<a href="#cafe/fractions">Visit Fraction Trail</a></details>`;
}
export function bindFractionTrail(state,{save,render,navigate,focus}={}){
 const scope=document.querySelector('.fraction-trail');if(!scope)return;
 const placeFocus=selector=>{if(focus)focus(selector);else document.querySelector(selector)?.focus();};
 const act=(fn,target)=>{if(fn()){save?.();render?.();if(target)placeFocus(typeof target==='function'?target():target);}};
 scope.querySelector('#trail-case')?.addEventListener('change',e=>act(()=>core.chooseTrailCase(state,e.target.value),'#trail-page-title'));
 scope.querySelectorAll('[data-trail-page]').forEach(b=>b.onclick=()=>act(()=>core.setTrailPage(state,b.dataset.trailPage),'#trail-page-title'));
 scope.querySelectorAll('[data-trail-cut]').forEach(b=>b.onclick=()=>act(()=>core.toggleTrailCut(state,Number(b.dataset.trailCut)),`[data-trail-cut="${b.dataset.trailCut}"]`));
 scope.querySelector('[data-trail-start]')?.addEventListener('click',()=>act(()=>core.startTrailFlag(state),'[data-trail-start]'));
 for(const [attr,delta] of [['back',-1],['forward',1]])scope.querySelector(`[data-trail-${attr}]`)?.addEventListener('click',()=>act(()=>core.moveTrailFlag(state,delta),()=>{const b=document.querySelector(`[data-trail-${attr}]`);return b&&!b.disabled?`[data-trail-${attr}]`:delta>0?'[data-trail-back]:not(:disabled)':'[data-trail-forward]:not(:disabled)';}));
 scope.querySelector('#trail-reading')?.addEventListener('input',e=>{if(core.setTrailReading(state,e.target.value)){save?.();e.target.removeAttribute('aria-invalid');e.target.setAttribute('aria-describedby','trail-reading-hint');scope.querySelector('#trail-input-error')?.remove();scope.querySelector('#trail-feedback-reading')?.remove();}});
 scope.querySelectorAll('[data-trail-check]').forEach(b=>b.onclick=()=>act(()=>core.checkTrail(state,b.dataset.trailCheck),()=>core.trailView(state).case.inputError?'#trail-input-error':`#trail-feedback-${b.dataset.trailCheck}`));
 scope.querySelectorAll('[data-trail-prepare]').forEach(b=>b.onclick=()=>act(()=>core.prepareTrailPartition(state,Number(b.dataset.trailPrepare)),`[data-trail-prepare="${b.dataset.trailPrepare}"]`));
 scope.querySelector('[data-trail-together]')?.addEventListener('click',()=>act(()=>core.prepareTrailTogether(state),'[data-trail-together]'));
 scope.querySelectorAll('[data-trail-help]').forEach(b=>b.onclick=()=>act(()=>core.setTrailHelp(state,b.dataset.trailHelp||null),b.dataset.trailHelp?'#trail-help-content':'.fraction-help summary'));
 scope.querySelector('[data-trail-example]')?.addEventListener('click',()=>act(()=>core.stepTrailExample(state),()=>core.trailView(state).case.exampleStep>=4?'#trail-help-content':'[data-trail-example]'));
 scope.querySelector('[data-trail-keep]')?.addEventListener('click',()=>act(()=>core.keepTrail(state),'#trail-kept-title'));
 scope.querySelector('[data-trail-recover]')?.addEventListener('click',()=>act(()=>core.recoverTrail(state),'#trail-page-title'));
 scope.querySelectorAll('[data-speak]').forEach(b=>b.addEventListener('click',()=>{if(core.useTrailSupport(state,'narration'))save?.();},{capture:true}));
}
